'use strict';

/**
* Construct a Givens plane rotation.
*
* @module @stdlib/blas/base/zrotg
*
* @example
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var zrotg = require( '@stdlib/blas/base/zrotg' );
*
* var za = new Complex128( 4.0, 3.0 );
* // returns <Complex128>
*
* var zb = new Complex128( 0.0, 0.0 );
* // returns <Complex128>
*
* var out = zrotg( za, zb );
* // returns <Float64Array>[ 4.0, 3.0, 1.0, 0.0, 0.0 ]
*
* za = new Complex128( 1.0, 3.0 );
* // returns <Complex128>
*
* zb = new Complex128( 2.0, 4.0 );
* // returns <Complex128>
*
* out = zrotg( za, zb );
* // out => <Float64Array>[ ~1.732, ~5.1961, ~0.5773, ~0.8082, ~0.1154 ]
*/

// MODULES //

var zrotg = require( './main.js' );


// EXPORTS //

module.exports = zrotg;
